// Converts the trained PID model (best_pid_model.txt) into pid_gains.h: a dependency-free C99 header
// with the gains, the fixed shaping constants and a ready-to-call control function for the firmware.
// It is the PID project's equivalent of the NN project's export_weights.cpp.
//
//   export_gains [model_file] [output_header]
#include "PidController.hpp"
#include "SimConfig.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <sstream>

// A C float literal: always has a decimal point or exponent, so "1" becomes "1.0f", never "1f".
static std::string F(float v) {
    std::ostringstream o;
    o << std::setprecision(9) << std::showpoint << v;
    std::string s = o.str();
    return s + "f";
}

int main(int argc, char** argv) {
    std::string model_path = argc > 1 ? argv[1] : "best_pid_model.txt";
    std::string out_path = argc > 2 ? argv[2] : "pid_gains.h";

    SimConfig cfg = LoadConfig("sim_config.txt");
    PidBrain pid(cfg);
    if (!pid.Load(model_path)) {
        std::cerr << "Error: could not load " << model_path << "\n";
        return 1;
    }

    std::ofstream h(out_path);
    if (!h.is_open()) {
        std::cerr << "Error: could not write " << out_path << "\n";
        return 1;
    }
    h << std::setprecision(9);
    h << "/* Generated by export_gains from " << model_path << ". Do not edit by hand. */\n"
      << "#ifndef PID_GAINS_H\n#define PID_GAINS_H\n\n"
      << "/* Trained gains. err = left - right ToF distance (metres); turn is a wheel speed (m/s). */\n"
      << "#define PID_KP " << F(pid.kp) << "\n"
      << "#define PID_KI " << F(pid.ki) << "\n"
      << "#define PID_KD " << F(pid.kd) << "\n\n"
      << "/* Fixed shaping (pid_params.txt) and hardware (sim_config.txt). */\n"
      << "#define PID_BASE_SPEED_FRAC " << F(pid.base_speed_frac) << "\n"
      << "#define PID_ERROR_CLIP_M " << F(pid.error_clip_m) << "\n"
      << "#define PID_INTEGRAL_LIMIT " << F(pid.integral_limit) << "\n"
      << "#define PID_D_FILTER_ALPHA " << F(pid.d_filter_alpha) << "\n"
      << "#define PID_SLOWDOWN_FRAC " << F(pid.slowdown_frac) << "\n"
      << "#define PID_MAX_SPEED_MPS " << F(pid.hw.max_linear_speed) << "\n"
      << "#define PID_TRACK_WIDTH_M " << F(pid.hw.track_width) << "\n"
      << "#define PID_LEFT_SENSOR_ANGLE_DEG " << F(cfg.sensors[pid.left_idx].angle_deg) << "\n"
      << "#define PID_RIGHT_SENSOR_ANGLE_DEG " << F(cfg.sensors[pid.right_idx].angle_deg) << "\n\n"
      << "typedef struct { float integral, prev_err, d_filtered; int has_prev; } PidState;\n\n"
      << "static inline float pid_clampf(float x, float lo, float hi) { return x < lo ? lo : (x > hi ? hi : x); }\n\n"
      << "/* Same arithmetic as PidBrain::Control in the simulator. Zero the state at start-up. */\n"
      << "static inline void pid_control(PidState* s, float left_m, float right_m, float dt,\n"
      << "                               float* v_left, float* v_right) {\n"
      << "    float err = pid_clampf(left_m - right_m, -PID_ERROR_CLIP_M, PID_ERROR_CLIP_M);\n"
      << "    float raw_d, turn, base, aturn;\n"
      << "    s->integral = pid_clampf(s->integral + err * dt, -PID_INTEGRAL_LIMIT, PID_INTEGRAL_LIMIT);\n"
      << "    raw_d = s->has_prev ? (err - s->prev_err) / dt : 0.0f;\n"
      << "    s->d_filtered = PID_D_FILTER_ALPHA * raw_d + (1.0f - PID_D_FILTER_ALPHA) * s->d_filtered;\n"
      << "    s->prev_err = err;\n"
      << "    s->has_prev = 1;\n"
      << "    turn = PID_KP * err + PID_KI * s->integral + PID_KD * s->d_filtered;\n"
      << "    turn = pid_clampf(turn, -PID_MAX_SPEED_MPS, PID_MAX_SPEED_MPS);\n"
      << "    aturn = turn < 0.0f ? -turn : turn;\n"
      << "    base = PID_BASE_SPEED_FRAC * PID_MAX_SPEED_MPS * (1.0f - PID_SLOWDOWN_FRAC * aturn / PID_MAX_SPEED_MPS);\n"
      << "    *v_left = pid_clampf(base - turn, -PID_MAX_SPEED_MPS, PID_MAX_SPEED_MPS);\n"
      << "    *v_right = pid_clampf(base + turn, -PID_MAX_SPEED_MPS, PID_MAX_SPEED_MPS);\n"
      << "}\n\n#endif /* PID_GAINS_H */\n";

    std::cout << "Wrote " << out_path << " (Kp " << pid.kp << ", Ki " << pid.ki << ", Kd " << pid.kd << ")\n";
    return 0;
}
